test('totals a simple order', () => {
  assert.deepStrictEqual(invoice([{ name: 'Mug', price: '19.99', qty: 1 }]), ['Mug: 19.99', 'Total: 19.99']);
});

test('prices like 19.99 do not lose a cent', () => {
  assert.deepStrictEqual(
    invoice([{ name: 'Mug', price: '19.99', qty: 3 }]),
    ['Mug: 59.97', 'Total: 59.97']
  );
});

test('refund lines print as a valid negative amount', () => {
  assert.deepStrictEqual(
    invoice([{ name: 'Refund', price: '-0.50', qty: 1 }]),
    ['Refund: -0.50', 'Total: -0.50']
  );
  assert.deepStrictEqual(
    invoice([{ name: 'Refund', price: '-19.99', qty: 1 }]),
    ['Refund: -19.99', 'Total: -19.99']
  );
});

test('percent discount rounds to the nearest cent', () => {
  // 10% of 19.99 = 1.999 -> 2 cents-worth -> 2.00 off? No: 1999 * 10 / 100 = 199.9 -> 200 cents
  assert.deepStrictEqual(
    invoice([{ name: 'Mug', price: '19.99', qty: 1 }], 10),
    ['Mug: 19.99', 'Discount: -2.00', 'Total: 17.99']
  );
});

